<?php

declare(strict_types=1);namespace OCA\MaintenanceTracker\Controller;use OCA\MaintenanceTracker\Exception\AccessDeniedException;use OCA\MaintenanceTracker\Exception\NotFoundException;use OCA\MaintenanceTracker\Exception\ValidationException;use OCA\MaintenanceTracker\Service\CurrentUser;use OCA\MaintenanceTracker\Service\SpecificationService;use OCA\MaintenanceTracker\Service\WorkspaceService;use OCP\AppFramework\Http;use OCP\AppFramework\Http\Attribute\ApiRoute;use OCP\AppFramework\Http\Attribute\NoAdminRequired;use OCP\AppFramework\Http\DataResponse;use OCP\AppFramework\OCS\OCSBadRequestException;use OCP\AppFramework\OCS\OCSForbiddenException;use OCP\AppFramework\OCS\OCSNotFoundException;use OCP\AppFramework\OCSController;use OCP\IRequest;
final class SpecificationController extends OCSController{public function __construct(string $appName,IRequest $request,private CurrentUser $user,private WorkspaceService $workspaces,private SpecificationService $service){parent::__construct($appName,$request);}#[NoAdminRequired]#[ApiRoute(verb:'GET',url:'/api/v1/assets/{assetUuid}/specifications')]public function index(string $assetUuid,?string $workspace=null):DataResponse{try{return $this->workspaces->runWithAccess($this->user->uid(),$workspace,'viewer',fn($c)=>new DataResponse(['items'=>$this->service->list($c,$assetUuid)]));}catch(AccessDeniedException $e){throw new OCSForbiddenException($e->getMessage(),$e);}catch(NotFoundException $e){throw new OCSNotFoundException($e->getMessage(),$e);}}#[NoAdminRequired]#[ApiRoute(verb:'POST',url:'/api/v1/assets/{assetUuid}/specifications')]public function create(string $assetUuid,array $specification,?string $workspace=null):DataResponse{try{return $this->workspaces->runWithAccess($this->user->uid(),$workspace,'editor',fn($c)=>new DataResponse($this->service->create($c,$assetUuid,$specification)->toApi($specification['componentUuid']??null),Http::STATUS_CREATED));}catch(AccessDeniedException $e){throw new OCSForbiddenException($e->getMessage(),$e);}catch(NotFoundException $e){throw new OCSNotFoundException($e->getMessage(),$e);}catch(ValidationException $e){throw new OCSBadRequestException($e->getMessage(),$e);}}}
